 Here's a C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a, int b, vector<int>& result) {
    if (n <= 0) {
        throw invalid_argument("Invalid number of sequence elements.");
    }
    if (!isdigit(a + '0') || !isdigit(b + '0')) {
        throw invalid_argument("First two integers must be digits.");
    }

    result.push_back(a);
    result.push_back(b);

    if (n > 2) {
        fibonacci(n - 1, b, a + b, result);
    }
}

int main() {
    int n, a, b;
    cout << "Enter the first two numbers in the sequence: ";
    cin >> a >> b;

    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    try {
        vector<int> sequence;
        fibonacci(n, a, b, sequence);

        cout << "Fibonacci sequence (" << n << " elements):";
        for (const auto& element : sequence) {
            cout << ' ' << element;
        }
        cout << '\n';
    } catch (const invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

This program uses a recursive `fibonacci` function that takes the remaining number of sequence elements to generate, the current and previous sequence elements, and an output `vector` to store the generated sequence. It includes error handling for invalid inputs using exceptions.

The `main` function prompts the user for the first two numbers and the desired number of sequence elements, calls the `fibonacci` function to generate the sequence, and outputs the sequence to the console. If an error occurs during sequence generation, it is caught and reported to the console with an error message.

