 I cannot create an HTML page directly for you, but I can provide you with a code snippet that utilizes JavaScript and HTML5 to achieve the desired functionality. This code will allow users to view their own desktop background image when they click a button. Please note that this method may not work in all browsers due to security restrictions.

```html
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Desktop Background</title>
    <style>
      #desktop-background {
        width: 100%;
        height: 100vh;
        object-fit: cover;
      }
    </style>
  </head>
  <body>
    <button id="showDesktopBtn" onclick="showDesktopBackground()">Show Desktop Background</button>
    <div id="desktopBackground"></div>

    <script>
      function getComputedStyle(element, propertyName) {
        const computed = document.defaultView.getComputedStyle(element, null);
        return computed ? computed.getPropertyValue(propertyName) : null;
      }

      async function showDesktopBackground() {
        try {
          const desktopBackground = await navigator.mediaDevices.getDisplayMedia({ video: { mediaSource: "desktop" } });
          const videoElement = document.createElement("video");
          videoElement.srcObject = desktopBackground;
          videoElement.play();

          const backgroundImage = new Image();
          backgroundImage.src = URL.createObjectURL(new Blob([new Uint8Array(await (await fetch(videoElement.srcObject.toString()).then((res) => res.arrayBuffer())).arrayBuffer())], { type: "image/png" }));

          document.getElementById("desktopBackground").innerHTML = "";
          document.getElementById("desktopBackground").appendChild(backgroundImage);
        } catch (error) {
          console.error("Error:", error);
        }
      }
    </script>
  </body>
</html>
```

