```csharp using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class AudioVisualizer : MonoBehaviour
{
    public Text debugText; // For debugging purposes only
    public RectTransform barsContainer; // Set up your rect transform for bars in the Unity editor
    public int barCount = 10; // Number of bars you want in the visualizer

    private float[] samples = new float[barCount];
    private AnalyseAudio m_Analyser;
    private AudioSource m_AudioSource;

    void Start()
    {
        m_AudioSource = GetComponent<AudioSource>();
        m_Analyser = GetComponent<AnalyseAudio>();

        if (m_Analyser == null)
            gameObject.AddComponent<AnalyseAudio>();

        m_Analyser.onSpectrumChanged += OnSpectrumChanged;

        m_AudioSource.Play();
    }

    void Update()
    {
        if (!m_AudioSource.isPlaying)
            Debug.Log("Please set an audio clip on the AudioSource component.");
    }

    void OnSpectrumChanged(float[] data)
    {
        for (int i = 0; i < Mathf.Min(data.Length, barCount); i++)
        {
            samples[i] = data[i];
            SetBarHeight(i, samples[i]);
        }
    }

    void SetBarHeight(int index, float height)
    {
        RectTransform bar = barsContainer.GetChild(index).GetComponent<RectTransform>();
        bar.localScale = new Vector3(1, height, 1);
    }
}
```

