 I'd be happy to help you write a PowerShell script for checking folders' Access Control Lists (ACLs) recursively to identify any SIDs that only exist in the SID history of users or groups in the Active Directory domain. This script will utilize the `System.Security.Principal.SecurityIdentifier` and `Microsoft.IdentityModel.Sid` .NET libraries, so please make sure these assemblies are imported before running the script.

```powershell
# Import required .NET assemblies
Add-Type -Path "C:\Windows\System32\WindowsPowerShell\v1.0\Microsoft.PowerTools.Security.psd1"
Import-Module Microsoft.PowerTools.Security

function Get-ADUserSidsHistory {
    param(
        [Parameter(Mandatory=$true)]
        [string]$samAccountName
    )

    $domain = New-Object System.DirectoryServices.ActiveDirectory.DomainContext("DC=example,DC=com")
    $user = $domain.FindUsersByName($samAccountName)[0]

    $sidHistory = $user.SIDHistory | ForEach-Object { $_.Value }

    return @$sidHistory
}

function Check-AclSidInSidHistory {
    param(
        [Parameter(Mandatory=$true)]
        [System.Security.Principal.SecurityIdentifier]$sid,
        [Parameter(Mandatory=$true)]
        [array]$sidHistory
    )

    return ($sidHistory -contains $sid)
}

